/**
 * 生成物ヘッダの検査（ARCH-BE-0001 の E5「手編集の禁止」。リンター側の第二防衛線）。
 *
 * `docs/generate` が書く生成物（`app/src/domain/generated/**`）は先頭に
 * `AUTO-GENERATED by \`npm run generate\` — 手編集禁止。` の JSDoc ヘッダを持つ
 * （生成器の正: `legacy/spec-tools/lib/gen-kit/code-emit.ts` の `generatedHeader`）。
 *
 * 生成物と実物の**内容**の食い違いは `npm run generate:check`（C1）が
 * 差分として検出するが、そちらは docs 側のコマンドであり、`app/` だけを触っている
 * ときには走らない。ヘッダを消して手編集すると、`app/` 側の検査（lint / typecheck /
 * test）だけを回している限り気づけない —— このルールはその**入口**（ヘッダを消す・
 * 中身をコメントごと書き換える）を lint の段階で塞ぐ。内容そのものの正しさは C1 が持つ
 * ので、ここで見るのは「ヘッダがある」ことだけである。
 */

/** 生成物ヘッダが必ず含む一意な文字列（`generatedHeader` の 1 行目と一致させる）。 */
const MARKER = "AUTO-GENERATED by `npm run generate`";

/** @type {import("eslint").Rule.RuleModule} */
export const generatedHeader = {
  meta: {
    type: "problem",
    docs: {
      description:
        "app/src/domain/generated/ 配下のファイルが AUTO-GENERATED ヘッダを持つことを必須化する",
    },
    schema: [],
    messages: {
      missing:
        "生成物（app/src/domain/generated/）にヘッダ(AUTO-GENERATED by `npm run generate` — 手編集禁止。)が見つからない。手で書いたファイルをここに置いていないか、ヘッダを消して手編集していないか確認すること。正しい生成物はルートの `npm run generate` が作る。",
    },
  },
  create(context) {
    return {
      Program(node) {
        const sourceCode = context.sourceCode ?? context.getSourceCode();
        const hasHeader = sourceCode
          .getAllComments()
          .some((comment) => comment.value.includes(MARKER));
        if (!hasHeader) {
          context.report({ node, loc: { line: 1, column: 0 }, messageId: "missing" });
        }
      },
    };
  },
};
